    end=Time.realtimeSinceStartup+10;float peak=0;while(m.ActualBombs==0&&Time.realtimeSinceStartup<end){peak=Mathf.Max(peak,m.trucks[0].body.linearVelocity.y);yield return null;}yield return null;peak=Mathf.Max(peak,m.trucks[0].body.linearVelocity.y);InputSystem.QueueStateEvent(pads[0],new GamepadState());Check(m.ActualBombs==1&&m.rules.state[bomb.id]==HaulerBallState.Spent&&m.rules.carried[0]==0&&m.rules.state[normal.id]==HaulerBallState.Loose,"actual fuse-ball intake triggers one explosion and releases physical carried cargo");Check(m.rules.points[0]==0&&peak>2&&normal.shape.enabled&&!normal.body.isKinematic,"bomb applies bounded actual truck motion, restores loose-ball collision and awards no hidden points");yield return new WaitForSeconds(.8f);Check(m.ActualBombs==1,"spent bomb cannot repeatedly detonate through compound or resting contacts");
   }
   m.SetupScreen();
  }
  IEnumerator Ram(HaulerMatch m)
  {
   pads[1]=InputSystem.AddDevice<Gamepad>("Actual opponent cargo ram fixture");m.SetupScreen();m.setup.count=2;m.AllBots();for(int i=0;i<2;i++){m.setup.players[i].source=BowlingSource.WholeController;m.setup.players[i].pad=pads[i];InputSystem.QueueStateEvent(pads[i],new GamepadState());}Check(m.StartMatch(),"two distinct human inputs start the physical cargo ram fixture");while(m.Countdown>0)yield return null;var ball=Array.Find(m.balls,b=>b.value==1);foreach(var other in m.balls)if(other!=ball)other.gameObject.SetActive(false);m.trucks[0].Prepare(new Vector3(0,.65f,0),Quaternion.identity);m.trucks[1].Prepare(new Vector3(0,.65f,40),Quaternion.Euler(0,180,0));SetBall(ball,new Vector3(0,1.1f,16));yield return new WaitForSeconds(.4f);InputSystem.QueueStateEvent(pads[0],new GamepadState().WithButton(GamepadButton.South));yield return null;InputSystem.QueueStateEvent(pads[0],new GamepadState{rightTrigger=1});float limit=Time.realtimeSinceStartup+8;while(m.rules.carried[0]==0&&Time.realtimeSinceStartup<limit)yield return null;Check(m.rules.carried[0]==1&&m.rules.points[0]==0,"real moving scoop collects the ram fixture cargo before the opponent approaches");InputSystem.QueueStateEvent(pads[1],new GamepadState{rightTrigger=1});limit=Time.realtimeSinceStartup+10;while(m.ActualRams==0&&Time.realtimeSinceStartup<limit)yield return null;for(int i=0;i<2;i++)InputSystem.QueueStateEvent(pads[i],new GamepadState());yield return null;Check(m.ActualRams==1&&m.rules.carried[0]==0&&m.rules.state[ball.id]==HaulerBallState.Loose&&ball.shape.enabled&&!ball.body.isKinematic,"genuine opposing truck impact spills held cargo through the same physical contact authority; rams="+m.ActualRams+" carried="+m.rules.carried[0]+" state="+m.rules.state[ball.id]+" positions="+m.trucks[0].body.position+" / "+m.trucks[1].body.position+" limiter="+m.trucks[0].tractorMotor.vehicle.powertrain.engine.revLimiterActive+","+m.trucks[1].tractorMotor.vehicle.powertrain.engine.revLimiterActive);Check(m.rules.points[0]==0&&m.rules.points[1]==0,"ramming and spilled balls never create hidden deposit points");m.SetupScreen();InputSystem.RemoveDevice(pads[1]);pads[1]=null;
  }
  static void SetBall(HaulerBall ball,Vector3 point){ball.body.interpolation=RigidbodyInterpolation.None;ball.body.position=point;ball.transform.position=point;ball.body.linearVelocity=ball.body.angularVelocity=Vector3.zero;ball.body.interpolation=RigidbodyInterpolation.Interpolate;Physics.SyncTransforms();}
  void Complete(){report.AppendLine("CHECKS="+checks+" ERRORS="+errors+"; platform="+Application.platform+"; capture="+SportsWindowCapture.EvidenceKind+"; actual NWH/PhysX scoop, cargo and bomb contacts plus software input; no human/device/listening certification.");File.WriteAllText(Folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;
